   362  tags
   363      : /* empty */
   364        {
   365          $$ = NULL;
   366        }
   367      | ':' tag_list
   368        {
   369          // Tags list is represented in the arena as a sequence
   370          // of null-terminated strings, the sequence ends with an
   371          // additional null character. Here we write the ending null
   372          //character. Example: tag1\0tag2\0tag3\0\0
   373
   374          compiler->last_result = yr_arena_write_string(
   375              yyget_extra(yyscanner)->sz_arena, "", NULL);
   376
   377          fail_if(compiler->last_result != ERROR_SUCCESS);
   378
   379          $$ = $2;
   380        }
   381      ;
   382
   383
   384  tag_list
   385      : _IDENTIFIER_
   386        {
   387          char* identifier;
   388
   389          compiler->last_result = yr_arena_write_string(
   390              yyget_extra(yyscanner)->sz_arena, $1, &identifier);
   391
   392          yr_free($1);
   393
   394          fail_if(compiler->last_result != ERROR_SUCCESS);
   395
   396          $$ = identifier;
   397        }
   398      | tag_list _IDENTIFIER_
   399        {
   400          char* tag_name = $1;
   401          size_t tag_length = tag_name != NULL ? strlen(tag_name) : 0;
   402
   403          while (tag_length > 0)
   404          {
   405            if (strcmp(tag_name, $2) == 0)
   406            {
   407              yr_compiler_set_error_extra_info(compiler, tag_name);
   408              compiler->last_result = ERROR_DUPLICATED_TAG_IDENTIFIER;
   409              break;
   410            }
   411
   412            tag_name = (char*) yr_arena_next_address(
   413                yyget_extra(yyscanner)->sz_arena,
   414                tag_name,
   415                tag_length + 1);
   416
   417            tag_length = tag_name != NULL ? strlen(tag_name) : 0;
   418          }
   419
   420          if (compiler->last_result == ERROR_SUCCESS)
   421            compiler->last_result = yr_arena_write_string(
   422                yyget_extra(yyscanner)->sz_arena, $2, NULL);
   423
   424          yr_free($2);
   425
   426          fail_if(compiler->last_result != ERROR_SUCCESS);
   427
   428          $$ = $1;
   429        }
   430      ;
