   358  u?int(8|16|32)(be)? {
   359
   360    char* text = yytext;
   361
   362    if (*text == 'u')
   363    {
   364      yylval->integer = 3;
   365      text++;
   366    }
   367    else
   368    {
   369      yylval->integer = 0;
   370    }
   371
   372    if (strstr(text, "int8") == text)
   373    {
   374      yylval->integer += 0;
   375      text += 4;
   376    }
   377    else if (strstr(text, "int16") == text)
   378    {
   379      yylval->integer += 1;
   380      text += 5;
   381    }
   382    else if (strstr(text, "int32") == text)
   383    {
   384      yylval->integer += 2;
   385      text += 5;
   386    }
   387
   388    if (strcmp(text, "be") == 0)
   389    {
   390      yylval->integer += 6;
   391    }
   392
   393    return _INTEGER_FUNCTION_;
   394  }
