   411  {digit}+(MB|KB){0,1}  {
   412
   413    char *endptr;
   414
   415    errno = 0;
   416    yylval->integer = strtoll(yytext, &endptr, 10);
   417
   418    if (yylval->integer == LLONG_MAX && errno == ERANGE)
   419    {
   420      yr_compiler_set_error_extra_info(compiler, yytext);
   421      error(ERROR_INTEGER_OVERFLOW);
   422    }
   423
   424    if (strstr(yytext, "KB") != NULL)
   425    {
   426      if (yylval->integer > LLONG_MAX / 1024)
   427      {
   428        yr_compiler_set_error_extra_info(compiler, yytext);
   429        error(ERROR_INTEGER_OVERFLOW);
   430      }
