   553  <regexp>\/i?s?  {
   554
   555    if (yyextra->lex_buf_len > 0)
   556    {
   557      alloc_sized_string(s, yyextra->lex_buf_len);
   558
   559      if (yytext[1] == 'i')
   560        s->flags |= SIZED_STRING_FLAGS_NO_CASE;
   561
   562      if (yytext[1] == 's' || yytext[2] == 's')
   563        s->flags |= SIZED_STRING_FLAGS_DOT_ALL;
   564
   565      *yyextra->lex_buf_ptr = '\0';
   566      strlcpy(s->c_string, yyextra->lex_buf, s->length + 1);
   567      yylval->sized_string = s;
   568    }
   569    else
   570    {
   571      syntax_error("empty regular expression");
   572    }
